import {VERSION} from './catalog.js';
// Every release must add an entry matching VERSION before packaging can succeed.
export const CHANGELOG=[
 {"build": 127, "version": "0.2.2", "title": "Sharp faces.", "items": ["Heroes, spirits and bosses are drawn pixel-perfect: eyes and other one-pixel details no longer flicker or disappear while moving.", "This covers the hero, ordinary spirits, guardians and every boss, at every Pixel sharpness setting.", "Your progress and unfinished journeys are kept."]},
 {"build": 126, "version": "0.2.1", "title": "A living world.", "items": ["Every map is redrawn: winding roads, cobbled squares, rivers and ponds, forests, fences, graves, lamps, crystals and reeds, plus its own buildings (mine, water mill, stilt hut, bell shrine). Fireflies, fog, falling leaves and rain.", "Night and lantern light: your lantern lights the way while lamps and windows glow. New Brightness setting.", "Every map has its own music, with new menu and boss themes and softer sound effects.", "Bosses for every map: Drowned Miller and Laumė of the Weir, Mirror Witch and Glass Heron, Antler King and Serpent King, each with its own attacks and colours. Whirlpools pull you; waves and millstones leave one safe lane.", "Seven new weapons: Smith's Cleaver, Frost Distaff, Viper Censer, Thunder Drum, Rowan Bow, Grave Scythe and Hail Sling. Six new artifacts: Lodestone, Fortune Coin, Hare's Foot, Falcon Feather, Owl Lens (see farther) and Four-leaf Clover.", "Weapons visibly grow with upgrades: bigger projectiles, trails, auras and sparks at levels 3, 5 and 7, and a golden look when evolved.", "Bestiary: defeat a spirit or boss to unlock its page with health, speed, damage, weaknesses and resistances. Weaknesses are real: +30% damage with orange numbers, resistances -25%.", "Fixes: the hero faces the way they walk; the boss name and health bar no longer hide behind the inventory; character prices are clearly labelled; the Magnet pulls crystals from about two screens instead of the whole map; spirits take on each map's colour; you wade slowly through water."]},
 {"build": 125, "version": "0.2.0", "title": "The bosses awaken.", "items": ["Public beta. Versions now count V0.2.0, V0.2.1 and onward up to V1.0.0, the store release. Updates are published at palcikevicius-glitch.github.io.", "The ritual meter now fills from defeated spirits (guardians much more) and boss damage instead of time. It stays frozen while a ritual or its echo is active and restarts from zero afterwards.", "Forgotten Village has its own bosses: the Scarecrow Warden, the Grave Hound and a rebuilt Bell Keeper. Lantern Quarry has the Lantern Thief and the Stone Breather. Each has its own sprite, movement, three phases and attacks.", "New boss attacks include crow fans, exploding straw dolls, pounces, claw sweeps, summoned packs, bell rings with a safe gap, bell pillars, a shrinking bell cage, blinking, stolen light, lantern mines, burrowing, rolling boulders, rock lines and dust breath.", "Boss arenas are larger: 400 units on every map, and the Drowned Mill arena is no longer cramped. Every attack shows its full danger area first and always leaves a way out.", "A boss health bar with the boss name appears at the top of the screen.", "Drowned Mill, Glass Marsh and Bellwood keep their current boss until their own bosses arrive in a later update. Your progress and unfinished journeys are kept."]},
 {"build": 124, "version": "0.1.9", "title": "A second light. Twin resin webs.", "items": ["Two optional paid revives per journey: 500 gold, then 1000 gold. Revive with half health and three seconds of protection. Banked and journey gold can pay; after both, death is final.", "Hero XP rewards increased by 25%; gem XP by 10%; power-up supply crates arrive 15% more frequently.", "New journeys begin with zero ritual charge. Existing journeys keep their charge.", "Resin Web fires two visible projectiles before spreading its webs, with 25% stronger damage per web.", "Health uses consistent rounding, so fractional maximum health can no longer display as 101/100."]},
 {"build": 119, "version": "0.1.8", "title": "Choose your next story.", "items": ["Continue, New game, Load and Settings are on the title screen. Each new game creates a separate hero without deleting older progress.", "Load shows each hero, level and played hours/minutes. Older heroes retain their progress and show the minimum known play time.", "Music can be played or muted with the same Settings button. The duplicate What’s new button is removed; update history remains under updates.", "Fireblast now has a bomb and spreading flames. Enemies take damage only when the visible fire front reaches them; gems and gold are still awarded.", "In-journey Settings show real damage per weapon, ritual and power-ups, including burning without counting overkill.", "Bread restores 30 base HP. Knockback is reduced by 45%.", "Boss arenas stop new enemy and guardian spawns. Existing intruders can be finished, while outside enemies cannot enter.", "Bellwood is smaller: 1400 by 1400 world units. Older journeys keep their progress and reachable loot."]},
 {"build": 118, "version": "0.1.7", "title": "Fewer spirits. Fiercer battles.", "items": ["Enemy populations are roughly halved and health is higher. Spatial combat queries remove repeated full-enemy scans without lowering graphics quality.", "Journey XP gains are halved. Weapon damage is 10% lower. Every defeated enemy awards exactly one gold; other rewards remain separate.", "Chests grant 1 / 3 / 5 upgrades with 80% / 17% / 3% chances and can be collected from farther away.", "Achievements now award shards and milestone character unlocks. Previously claimed achievements can collect the new extras once without repeating gold.", "Bosses gain health phases, aimed volleys, marked blasts, charges and expanding shockwaves. Armor and shields reduce damage but cannot erase every hit.", "Basic missiles hit one target until final mastery. Raven splash unlocks late; Lantern aims at enemies and delayed marks track targets during the first part of their warning.", "Combining two evolved weapons consumes both and leaves one Ultimate in one equipment slot.", "Enemies arrive beyond the screen. Drowned Mill is narrower and winding; houses, ruins and wells add landmarks to the world.", "Time Stop lasts three combat seconds, pauses enemy spawns and has a blue blast. Fireblast has a new explosion and leaves gems; Magnet pulls gems visibly toward you."]},
 {"build": 117, "version": "0.1.6", "title": "V0.1.6 TEST — update verification.", "items": ["Test release for checking the in-game download and update flow.", "Android checks the download size, SHA-256, package and signing identity before opening the system installer.", "Your saved progress and unfinished journey are preserved. Finish a journey before applying an update."]},
 {"build": 115, "version": "0.1.4", "title": "The horde finds its way.", "items": ["Much denser waves now bring 3\u201312 enemies at a time. Population limits grow from 32 in the opening to 360 late in a journey.", "Grouped assaults arrive from one direction every 28 seconds, beginning at 18 seconds. Packs contain 12\u201336 enemies and respect population limits.", "Blocked enemies steer around trees and rocks instead of pressing against them forever. Freeze and root effects still intentionally stop movement.", "Boss arenas have denser reinforcements. Your progress, loot and unfinished journey remain saved."]},
 {"build": 114, "version": "0.1.3", "title": "Let the souls rise.", "items": ["Defeated enemies flash white, dissolve and release a rising pixel soul. Stronger spirits leave a warm golden trail. Reduced-motion settings soften the flash.", "Combat and movement are 10% faster than V0.1.2. Enemy arrival rates and population limits increase by about 12% throughout the journey; map timers keep their real duration.", "Projectiles now hit the visible body of enemies. Moon Sickle has a blade-sized hit area and can strike once on each outward and return pass.", "Elite arrival and chest-collection announcements are removed. Floating loot icons, minimap markers and off-screen arrows remain.", "Forgotten Village and Glass Marsh have endless terrain. Lantern Quarry is horizontal, Drowned Mill vertical, and Bellwood a square arena. Boundaries appear in the world and minimap.", "Your saved progress remains intact. Existing journeys gain their new boundaries around the current location, and saved loot is kept inside reachable terrain."]},
 {"build": 113, "version": "0.1.2", "title": "Earn the awakening.", "items": ["A gentler opening grows into controlled late-game pressure. Normal population caps rise from 12 to 160, and late enemies reach tiers 7 and 8.", "Movement and combat run 30% slower, including your character. The journey still lasts 20 active real minutes.", "Weapons now have seven levels with twelve individual upgrade paths. Artifacts have six smaller steps; their inventory cells show levels.", "Guardians and bosses drop floating chests. They award 1, 3 or 5 upgrades with 55.56%, 33.33% and 11.11% probabilities, revealed through animated reels.", "A level 7 weapon and matching level 6 artifact unlock one 70% evolution chance per collected elite chest. Recipes stay hidden until discovered. Ultimate fusions also come from chests.", "Evolution damage no longer receives a hidden 2.8 multiplier. Overlapping effects share a hit cadence; sustained weapons have a brief recovery window that Mirror Shard reduces.", "Your actual drawn path becomes a fixed ritual boundary. Each character has a distinct purpose, from shelter and roots to hunting ravens and a lightning vortex.", "A circular minimap shows you, enemies and elite loot. Off-screen chest arrows guide you back; Settings sits beside the map.", "Four source-derived arrangements of the supplied Morning Light recording last over three minutes each. Boss music is faster and heavier, with smooth scene transitions.", "Existing gold, characters, skills, achievements, discoveries, settings and unfinished journeys are preserved. Revealing or reloading a chest cannot award it twice."]},
 {"build": 112, "version": "0.1.1", "title": "Awaken the storm.", "items": ["Enemy health is doubled, guardian health tripled and main boss health quadrupled. Movement and contact damage keep their previous values.", "Main bosses clear a circular arena and telegraph three attack patterns. Defeat a boss and collect its chest for three saved equipment rewards.", "All 24 evolutions now have stronger individual mechanics. Ravens dive and burst, needles pierce, Crown blades orbit continuously and homing shots expire within two seconds.", "Each of the twelve characters has a unique charged ritual. Close a movement loop to unleash it; read its effect in Characters.", "Artifacts grant small, visible bonuses to armor, damage, speed, health, effect area, duration, recovery or reach.", "Six final masteries unlock after learning every skill in their branch. All 54 skills are obtainable. Forty new challenges bring the achievement total to 80.", "Four original retro soundtracks run for over three minutes each, with crossfades and a Play music retry button. Pixel sharpness, effect pixels, intensity and shake are adjustable.", "Existing progress and unfinished journeys are migrated. New challenge records start now; chest rewards cannot be collected twice after reloading."]},
 {"build": 111, "version": "0.1.0", "title": "A world in pixels.", "items": ["Twelve original full-body pixel characters now have four-frame walking animations and matching menu portraits.", "Six enemy tiers have distinct pixel sprites. Guardians and the Bell Keeper have their own larger animated forms.", "Weapons, artifacts, power-ups, crystals, trees, rocks and crates are redrawn with crisp pixel edges. Each map has its own tiled ground palette.", "Weapon-specific spells and impacts now render as pixel effects. A new forest chapel scene, lantern icon and retro menu frames complete the look.", "Your gold, characters, achievements, skills, discoveries, settings and unfinished journey remain saved."]},
 {"build": 109, "version": "0.0.9", "title": "Twelve souls. A longer song.", "items": ["Twelve characters each have a fixed starting weapon. Unlock them with earned gold in Characters; choose a character before your journey.", "Forty achievements award gold once each. Open Achievements in the camp corner to track progress and claim rewards.", "Skills open in a popup. Health, Strength, Ritual, Speed, Fortune and Knowledge contain 48 skills, all obtainable for one point each. Existing learned skills are kept.", "Grave Compass marks enemy positions and explodes after 0.9 seconds. Moon Sickle travels farther before returning.", "Ordinary tier 1–2 enemies drop blue crystals worth 1 XP, tier 3–4 green worth 3 XP, and tier 5–6 red worth 9 XP. Boss and guardian bonuses remain.", "Four new instrumental arrangements last over three minutes each, with developed themes, bridges and reprises. They are clean reconstructions inspired by the supplied fragment, not isolated original stems.", "Gold, ranks, collected weapons, discoveries, settings and unfinished journeys are preserved. New lifetime kill, guardian and ritual counters begin with this update."]},
 {"build": 108, "version": "0.0.8", "title": "Move from anywhere. Remember every update.", "items": ["The joystick now appears exactly where you touch the arena and disappears when you release. Its size and opacity remain adjustable.", "Movement stops when a touch ends, is cancelled or the game is paused. Extra fingers and menu buttons do not move the joystick.", "The latest changes and all earlier recorded updates are shown together, newest first. Scroll down in What’s new or Updates to read the history."]},
 {"build": 107, "version": "0.0.7", "title": "A measured hunt. A new constellation.", "items": ["Enemy pressure is reduced. Each five-minute stage begins with its lowest tier, adds the second at 2:00 and the third at 4:00.", "A compact HUD puts equipment on the left, your level beside it, time in the center and gold on the right. Ritual charge appears below your character.", "The skill tree is rebuilt with 48 unique talents across six branching constellations. Old skill points are refunded; your other progress is kept.", "Weapons have distinct detailed attack animations. Held weapon sprites are removed. Enemy defeats add restrained blood bursts, fading stains and varied impact sounds.", "A new title screen leads into camp. Four arrangements of the supplied audio fragment accompany the title, camp, journey and boss battles, with smooth crossfades."]},
 {"build": 106, "version": "0.0.6", "title": "A crowded road. A deeper Arsenal.", "items": ["Enemy waves are much denser. Every five minutes the three enemy tiers rise: 1/2/3, 2/3/4, 3/4/5, then 4/5/6.", "Three guardians arrive in each five-minute stage. Collect their Instant Upgrade to raise an owned weapon by one level.", "Supply crates arrive about four times per 2.5 minutes, with at most four present. You can walk through them.", "Carry six weapon slots and six artifacts. The upper-left inventory shows every slot and eight new artifact illustrations.", "Gift choices rotate between new weapons, owned upgrades and artifacts. Undiscovered weapon families receive priority while slots remain.", "Journey and hero levels require twice as much XP. Forge gold costs are tripled and shard costs doubled. Existing progress is preserved.", "Ranks now run from D Common to SSS+ Divine, with individual colors, fiery SSS and a luminous SSS+."]},
 {"build": 105, "version": "0.0.5", "title": "A harder road. A stronger Arsenal.", "items": ["New version names start at V0.0.5. Your progress and settings are migrated automatically.", "Complete each journey to reveal the next map. Locked maps are shown as ???.", "Rocks and trees block movement. Break supply crates to find Time Stop, Magnet, Fireblast or Journey XP.", "Mini bosses arrive at 4, 9, 14 and 19 minutes where applicable. Larger enemy waves make every journey more demanding.", "Health bars now appear above your hero and every enemy.", "Your Arsenal and starting weapons show only collected weapons. Find new weapons during a journey.", "Twelve physical weapon illustrations replace the old symbols.", "Weapons cap at level 6. Levels 2, 3, 5 and 6 add an attack unit; levels 4 and 6 add 15% attack speed.", "Each weapon keeps its own attack type. Level 6 plus a compatible artifact and Evolution core unlocks one of its two evolutions.", "Older saves did not record individual map victories or every weapon pickup. Recorded ranks, discoveries and the saved journey are used to recover what can be proven."]},
 {build:104,version:'1.04',title:'Sharper weapons. True homing.',items:[
  'Weapon levels now improve damage, attack speed and reach.',
  'Compatible weapons gain an extra projectile or target at levels 3 and 6.',
  'Upgrade cards show exact before-and-after weapon stats.',
  'Amber needles and ravens follow moving enemies and retarget after a hit or defeat.',
  'Evolved weapons keep their level-8 scaling.',
  'Update notes appear after installation and remain available in Settings.'
 ]},
 {build:103,version:'1.03',title:'A living world.',items:[
  'Automatic progress backups protect your hero, equipment, discoveries and settings.',
  'Journey levels require about 35% more XP.',
  'Three original music loops, animated menus and richer combat effects.'
 ]}
];
export const currentChanges=()=>{const entry=CHANGELOG.find(n=>n.build===VERSION.build);if(!entry)throw Error('Release notes required for this build');return entry;};
export const unreadChanges=profile=>CHANGELOG.filter(n=>n.build<=VERSION.build&&n.build>(Number.isSafeInteger(profile.lastSeenBuild)?profile.lastSeenBuild:0));
